"""Build the local review page from actual EXE captures, concepts and test evidence."""
from pathlib import Path
from html import escape

root=Path(__file__).resolve().parents[2]
out=root/'Docs/VisualDirection/CoastalStadiums'
labels=['Exterior / arrival side','Exterior / opposite side','Main entrance at player height','Stone and trim close-up','Concourse','Spectator aisle','Playing-area entrance','Open sky from play area']
suffixes=['01_Exterior_Front','02_Exterior_Rear','03_Entrance','04_Material_Close','05_Concourse','06_Spectator_Aisle','07_Playing_Entrance','08_Open_Sky']
parts=[]
for sport,code in [('Football','F1'),('Basketball','B1')]:
    cards=''.join(f'<figure><a href="GameReview/{sport}_{suffix}.png" target="_blank"><img loading="lazy" src="GameReview/{sport}_{suffix}.png" alt="{sport}: {label}"></a><figcaption><span>{i+1:02d}</span>{label}</figcaption></figure>' for i,(suffix,label) in enumerate(zip(suffixes,labels)))
    parts.append(f'<section id="{sport.lower()}"><div class="sectionhead"><div><p class="eyebrow">{code} / ACTUAL WINDOWS EXE</p><h2>{sport}</h2></div><p>Eight 1920 × 1080 views.<br>Open any image to inspect the original.</p></div><video controls preload="metadata" poster="GameReview/{sport}_03_Entrance.png" src="GameReview/{sport}_Walkthrough.mp4"></video><p class="caption">Continuous controller walkthrough: dock → entrance → playing area → dock return → spectator stairs → concourse. 1280 × 720 / 30 fps; no audio.</p><div class="grid">{cards}</div></section>')
concepts=''.join(f'<figure><a href="Concepts/{p.name}" target="_blank"><img loading="lazy" src="Concepts/{p.name}" alt="Design concept {escape(p.stem)}"></a><figcaption>{escape(p.stem.replace("_"," "))} · CONCEPT</figcaption></figure>' for p in sorted((out/'Concepts').glob('*.png')))
performance=out/'GameReview/frame-performance.txt'
perf=escape(performance.read_text()) if performance.exists() else 'Normal-player performance evidence will appear here after validation.'
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>F1 / B1 · Coastal stadium review</title><style>
:root{color-scheme:light;--ink:#14383e;--muted:#567277;--teal:#087b83;--paper:#f6f2e8}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}a{color:var(--teal)}header{padding:70px max(6vw,24px) 45px;background:#143f45;color:#fff}header p{max-width:760px;color:#cee0d9}h1{font-size:clamp(36px,5vw,64px);line-height:1.05;letter-spacing:-2px;margin:14px 0 22px}h2{font-size:36px;line-height:1.1;margin:6px 0}.eyebrow{font-size:12px;font-weight:700;letter-spacing:2px;text-transform:uppercase}nav{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}nav a{background:#e6f0e9;color:#143f45;text-decoration:none;padding:10px 18px;border-radius:5px}main{max-width:1500px;padding:0 max(4vw,20px);margin:auto}section{padding:60px 0;border-bottom:1px solid #cbd3c7}.sectionhead{display:flex;justify-content:space-between;align-items:end;margin-bottom:24px}.sectionhead>p{color:var(--muted);text-align:right}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}figure{margin:0;background:white;border:1px solid #d9ddd2;border-radius:7px;overflow:hidden}figure img{display:block;width:100%;aspect-ratio:16/9;object-fit:cover}figcaption{padding:15px 18px;font-weight:600}figcaption span{font-size:12px;color:var(--teal);margin-right:12px}video{display:block;width:100%;max-height:700px;background:#163f44;border-radius:8px}.caption{color:var(--muted);font-size:14px;margin:10px 0 26px}.evidence{padding:24px;background:white;border:1px solid #d9ddd2;border-radius:7px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.7 ui-monospace,monospace}details{margin:35px 0}summary{cursor:pointer;font-size:22px;font-weight:650;margin-bottom:25px}.concepts img{object-fit:contain;background:#eee8dc}footer{padding:30px 0 55px;color:var(--muted)}@media(max-width:720px){.grid{grid-template-columns:1fr}.sectionhead{display:block}.sectionhead>p{text-align:left}header{padding-top:42px}}
</style><header><div class="eyebrow">Palm Shore / Windows review</div><h1>Stadiums by the sea.</h1><p>F1 football keeps its pitch and seating layout, with coastal entrances and connected spectator routes. B1 basketball opens to the sky, with cream arcades, teal trim, timber details and perimeter scoreboards.</p><nav><a href="#football">Football</a><a href="#basketball">Basketball</a><a href="#validation">Validation</a><a href="#concepts">Design concepts</a></nav></header><main>'''+''.join(parts)+f'''<section id="validation"><p class="eyebrow">Evidence / reproducible checks</p><h2>Validation and performance</h2><p><strong>Known limitation:</strong> Unity can report a shutdown crash after Windows UI Automation interacts with the player. See the validation report for the engine issue and measured results.</p><p>The screenshots and videos above are rendered by the Windows executable. The concepts below are separate design references.</p><div class="evidence"><p><a href="GameReview/review.txt">Offline route and camera checks</a> · <a href="GameReview/frame-performance.txt">Normal-player frame timing</a> · <a href="GameReview/build-evidence.json">Reviewed build hashes</a> · <a href="GameReview/VALIDATION.md">Validation and known limitations</a> · <a href="../../COASTAL-STADIUMS.md">Implementation and validation report</a></p><pre>{perf}</pre><p>Measured on the available RTX 4050 laptop. This is a short Windows benchmark; Android tuning and sustained thermal profiling are deferred.</p></div></section><section id="concepts"><p class="eyebrow">Design direction / imagegen</p><h2>Concepts, separate from the game</h2><p>Six planning images informed the coastal palette, architecture and circulation. They are not screenshots or a claim of identical in-game rendering. <a href="Concepts/PROMPTS.md">Saved prompts and references</a>.</p><details><summary>Show all six concepts</summary><div class="grid concepts">{concepts}</div></details></section><footer>Sources: editable Blender venues, reusable coastal material library and Unity builders. Current player (build locally): Builds/WindowsFinal/WhatTheFish.exe.</footer></main></html>'''
(out/'index.html').write_text(html,encoding='utf-8')
print(out/'index.html')
